uniform float uCastProgress,uReleaseAge,uAutoPreview;
attribute vec3 aO; attribute float aT, aK; attribute vec2 aC; uniform float uTime; varying vec3 vL, vN, vV; varying float vU, vK, vCH, vFill;
    void main(){
      float u = uAutoPreview>.5 ? uTime-aT : aC.x*clamp(uCastProgress,0.,1.)+max(uReleaseAge,0.), CH = aC.x; if (u < 0. || u > CH + .6){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float p = clamp(u/CH, 0., 1.), grow = 1. - (1. - p)*(1. - p);
      float rel = u - CH, snap = rel > 0. ? exp(-rel*18.)*.06 : 0.;              // the shell tightens once on release
      float R = mix(.45, 1.05 + .1*aK, grow)*(1. - snap)*(1. + .035*sin(position.y*5. + position.x*4. + u*1.7 + aK*2.));
      vec3 n = normalize(position);
      vec3 W = aO + vec3(0., 1.05, 0.) + n*R*vec3(1., 1.18, 1.);
      vL = n; vN = n; vV = normalize(cameraPosition - W); vU = u; vK = aK; vCH = CH; vFill = aC.y;
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.);
    }

